package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaDecimalWholeQuotientsTest {
 @Test public void originalNaSixDividendsIncludeFiniteAndExactFractionResults(){var l=GlobalCurriculum.limits("na-nied-primary-2024-v1","decimalDivInt",6);assertTrue(DecimalWholeQuotients.selected("decimalDivInt",l));Generator g=new Generator(new Random(2932));List<String> recent=new ArrayList<>();Set<Integer> places=new HashSet<>();Set<String> formats=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next("decimalDivInt",recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=DecimalWholeQuotients.read(q);assertNotNull(v);places.add(new BigDecimal(v.raw()).scale());formats.add(q.answerFormat);Rational expected=Expression.number(v.raw()).div(Rational.of(v.divisor()));String input=q.answerFormat.equals("fraction")?expected.toString():expected.decimalText();q.answers[0]="poison";q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(input)).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(Set.of(1,2,3),places);assertEquals(Set.of("fraction","decimalValue"),formats);}
 @Test public void exactFractionHelpAndFiniteMoreThanThreePlacesKeepTheirMeaning(){Question q=DecimalWholeQuotients.make("1.0",3);assertEquals("fraction",q.answerFormat);q.answers[0]="poison";q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of("1/3")).correct());assertFalse(new Checker().check(q,List.of(),List.of("0.333")).correct());HelpPlan h=HelpPlan.forQuestion(q);List<String> entries=List.of("1.0","3","1","10","10","30","10","1","3");assertEquals(9,h.size());for(int i=0;i<entries.size();i++)assertTrue(h.step(i).accepts(entries.get(i)));assertFalse(h.canTransfer());q=DecimalWholeQuotients.make("99.9",16);assertEquals("decimalValue",q.answerFormat);assertTrue(new Checker().check(q,List.of(),List.of("6.24375")).correct());assertFalse(new Checker().check(q,List.of(),List.of("6.244")).correct());}
 @Test public void zeroAndInvalidDivisorsRemainDistinct(){Question q=DecimalWholeQuotients.make("0.000",99);q.answers[0]="poison";assertTrue(new Checker().check(q,List.of(),List.of("0")).correct());for(int divisor:List.of(0,-1,100)){try{DecimalWholeQuotients.make("1.00",divisor);fail("divisor"+divisor);}catch(IllegalArgumentException expected){}}assertFalse(DecimalWholeQuotients.selected("decimalDivInt",CurriculumLimits.NONE));q=DecimalWholeQuotients.make("1.0",2);q.answerFormat="decimal";assertTrue(new Checker().check(q,List.of(),List.of("0.5")).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("1/2")).status);assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0")).status);}
}
